# Minimal prep-list + staff schedule prototype for small restaurants
import json, sys
from datetime import date

DEFAULT = {"staff": [], "prep": [], "orders": []}

def load(path="data.json"):
    try:
        with open(path) as f:
            return json.load(f)
    except FileNotFoundError:
        return DEFAULT

def save(data, path="data.json"):
    with open(path, "w") as f:
        json.dump(data, f, indent=2)

def add_staff(data, name, shifts):
    data["staff"].append({"name": name, "shifts": shifts})

def add_prep(data, item, qty, unit, par):
    data["prep"].append({"item": item, "qty": qty, "unit": unit, "par": par})

def low_prep(data):
    return [p for p in data["prep"] if p["qty"] < p["par"]]

def order_list(data):
    return [f"{p['item']}: order {p['par'] - p['qty']} {p['unit']}" for p in low_prep(data)]

if __name__ == "__main__":
    d = load()
    if len(sys.argv) > 1 and sys.argv[1] == "demo":
        add_staff(d, "Lupe", ["Mon 4-10pm", "Thu 4-10pm"])
        add_prep(d, "tortillas", 20, "dozen", 40)
        add_prep(d, "cilantro", 3, "bunch", 6)
        save(d)
    print("Low on prep:")
    for line in order_list(d):
        print(" -", line)
